// Set global product variables
window.productAuthenticity = 'REAL';
window.productItem = 'Jesus Clothes';
window.productOrigin = 'from Jerusalem';
window.stockLevel = 'in stock';
window.listPrice = '45.99';

console.log('Product globals loaded:', {
    authenticity: window.productAuthenticity,
    item: window.productItem,
    origin: window.productOrigin,
    stock: window.stockLevel,
    price: window.listPrice
});

// Wait for the page to load and DOM to be ready
document.addEventListener('DOMContentLoaded', function() {
    // Check if global variables are available
    if (typeof window.productAuthenticity !== 'undefined' && 
        typeof window.productItem !== 'undefined' && 
        typeof window.productOrigin !== 'undefined' &&
        typeof window.listPrice !== 'undefined') {

        // Assemble the product name
        const assembledName = window.productAuthenticity + ' ' + window.productItem + ' ' + window.productOrigin;

        // Fill the form fields
        const nameInput = document.querySelector('input[name="product[name]"]');
        const priceInput = document.querySelector('input[name="product[price]"]');
        const stockInput = document.querySelector('input[name="product[stock]"]');

        if (nameInput) {
            nameInput.value = assembledName;
        }

        if (priceInput) {
            priceInput.value = window.listPrice;
        }

        if (stockInput) {
            stockInput.value = window.stockLevel;
        }

        console.log('Product form pre-filled with:', {
            name: assembledName,
            price: window.listPrice,
            stock: window.stockLevel
        });
    } else {
        console.warn('Some global product variables are missing');
    }
});

